# frozen_string_literal: true

# A colour theme, read from config/themes.yml — static data generated by
# `bin/rails themes:import` from the Omarchy themes on the machine that ran it.
# Nothing here touches the filesystem beyond that one checked-in file, so themes
# work identically on a server that has never heard of Omarchy.
class Theme
  # What "follow the system" resolves to. Both must exist in config/themes.yml.
  SYSTEM = 'system'
  SYSTEM_DARK = 'tokyo-night'
  SYSTEM_LIGHT = 'catppuccin-latte'

  TOKENS = %w[canvas surface raised line ink ink-muted ink-faint accent ok warn danger info].freeze

  attr_reader :slug, :name, :mode, :tokens, :contrast

  class << self
    def all
      @all ||= definitions.map { |slug, attributes| new(slug, attributes) }
                          .sort_by { |theme| [theme.mode == 'dark' ? 0 : 1, theme.name] }
    end

    def find(slug)
      by_slug[slug.to_s]
    end

    def exists?(slug)
      slug.to_s == SYSTEM || by_slug.key?(slug.to_s)
    end

    def slugs
      by_slug.keys
    end

    # Nil or "system" means no attribute is rendered and the stylesheet's media
    # query decides.
    def attribute_for(slug)
      return nil if slug.blank? || slug.to_s == SYSTEM

      find(slug)&.slug
    end

    # A last resort so a missing or truncated config/themes.yml renders an
    # ugly page rather than raising from inside the layout.
    def fallback
      @fallback ||= new('fallback', {
                          'name' => 'Fallback', 'mode' => 'dark', 'contrast' => 12.0,
                          'tokens' => { 'canvas' => '#0e0e14', 'surface' => '#13141c',
                                        'raised' => '#1a1b26', 'line' => '#2b2d3a',
                                        'ink' => '#c0caf5', 'ink-muted' => '#b4bee6',
                                        'ink-faint' => '#414868', 'accent' => '#7aa2f7',
                                        'ok' => '#9ece6a', 'warn' => '#e0af68',
                                        'danger' => '#f7768e', 'info' => '#449dab' }
                        })
    end

    def dark
      all.select(&:dark?)
    end

    def light
      all.reject(&:dark?)
    end

    def reload!
      @all = @by_slug = @definitions = nil
    end

    private

    def by_slug
      @by_slug ||= all.index_by(&:slug)
    end

    def definitions
      @definitions ||= YAML.load_file(Rails.root.join('config/themes.yml')) || {}
    end
  end

  def initialize(slug, attributes)
    @slug = slug
    @name = attributes['name']
    @mode = attributes['mode']
    @tokens = attributes['tokens'] || {}
    @contrast = attributes['contrast']
  end

  def dark?
    mode == 'dark'
  end

  def token(name)
    tokens[name.to_s]
  end

  # Enough of the palette to draw a swatch in the picker without loading the
  # whole theme.
  def preview
    tokens.values_at('canvas', 'surface', 'accent', 'ok', 'warn', 'danger')
  end

  def ==(other)
    other.is_a?(Theme) && other.slug == slug
  end
  alias eql? ==

  delegate :hash, to: :slug
end
